"""Small deterministic public fixtures; stdlib only, no network or SUT imports."""
import base64,gzip,hashlib,hmac,json,pathlib,zlib
HERE=pathlib.Path(__file__).resolve().parent
archive=('owned fixture archive entry\n'+''.join(f'row:{i:04d}:abc-def-ghij\n' for i in range(256))).encode()
sheet=bytes((i*29+(i//251)*31)%256 for i in range(4096))
pack=b'PACK\x00\x00\x00\x02\x00\x00\x00\x01'+bytes(range(256))*8
key=b'PUBLIC-FIXTURE-HMAC-KEY-NO-SECRET'
raw=zlib.compressobj(wbits=-15)
v={'archive':base64.b64encode(archive).decode(),'gzip':base64.b64encode(gzip.compress(archive,mtime=0)).decode(),'sheet':base64.b64encode(sheet).decode(),'raw':base64.b64encode(raw.compress(sheet)+raw.flush()).decode(),'pack':base64.b64encode(pack).decode(),'key':base64.b64encode(key).decode(),'sha1pack':hashlib.sha1(pack).hexdigest(),'sha256archive':hashlib.sha256(archive).hexdigest(),'sha1archive':hashlib.sha1(archive).hexdigest(),'sha256sheet':hashlib.sha256(sheet).hexdigest(),'hmacpack':hmac.new(key,pack,'sha256').hexdigest()}
(HERE/'vectors.js').write_text('// Public deterministic fixture bytes, never credentials. Generated by make_vectors.py.\nexport const vectors='+json.dumps(v,indent=2)+';\nexport const bytes=name=>Uint8Array.from(atob(vectors[name]),c=>c.charCodeAt(0));\n')
print({k:len(x) for k,x in [('archive',archive),('sheet',sheet),('pack',pack)]})
